<?php declare(strict_types=1);
require dirname(__DIR__).'/native/bootstrap.php';
use Kulturhus\Native\TestSupport;
use Kulturhus\Native\Shared\{Access,Db};
use Kulturhus\Native\Chat\{Schema,Workspace,Polls,Attachments,Notifications,Conflict};
use Kulturhus\Native\Web\ChatView;
$checks=0;
function check(bool $ok,string $label):void{global $checks;if(!$ok)throw new RuntimeException('FAIL: '.$label);$checks++;}
function denied(callable $operation,string $label):void{try{$operation();}catch(DomainException){check(true,$label);return;}check(false,$label);}
$db=TestSupport::db();$seeds=TestSupport::seed($db);Schema::install($db);Schema::install($db);
$run='chat-flow-'.bin2hex(random_bytes(6));$club=$run.'-club';$actors=[];
foreach($seeds as $role=>$seed){$actors[$role]=$run.'-'.$role;Db::run($db,'INSERT INTO native_users(id,club_id,name) VALUES(?,?,?)',[$actors[$role],$role==='outsider'?$run.'-foreign':$club,'Synthetischer Chat '.$role]);Db::run($db,'INSERT INTO native_grants(actor_id,module,capability) SELECT ?,module,capability FROM native_grants WHERE actor_id=?',[$actors[$role],$seed]);}
$adminAccess=new Access($db,$actors['admin']);$editorAccess=new Access($db,$actors['editor']);$readerAccess=new Access($db,$actors['reader']);$foreignAccess=new Access($db,$actors['outsider']);
$admin=new Workspace($db,$adminAccess);$editor=new Workspace($db,$editorAccess);$reader=new Workspace($db,$readerAccess);$outsider=new Workspace($db,$foreignAccess);
$editorAlerts=new Notifications($db,$editorAccess);$readerAlerts=new Notifications($db,$readerAccess);$adminAlerts=new Notifications($db,$adminAccess);
$root=dirname(__DIR__,2).'/.local/native-chat-workflow-tests/'.$run;mkdir($root,0700,true);
$files=new Attachments($db,$adminAccess,$root.'/files');$editorFiles=new Attachments($db,$editorAccess,$root.'/files');$readerFiles=new Attachments($db,$readerAccess,$root.'/files');$foreignFiles=new Attachments($db,$foreignAccess,$root.'/files');
$view=new ChatView($db,$adminAccess,$root.'/files','local-csrf');$editorView=new ChatView($db,$editorAccess,$root.'/files','local-csrf');$readerView=new ChatView($db,$readerAccess,$root.'/files','local-csrf');
$key=static fn()=>bin2hex(random_bytes(16));
check($editorAlerts->state()['enabled']===false&&$editorAlerts->state()['version']===0,'notifications opt in by default');
$state=$editorAlerts->set(true,0);check($state['enabled']&&$state['version']===1,'opt in versioned');
denied(fn()=>$editorAlerts->set(false,0),'stale notification preference rejected');
$readerAlerts->set(true,0);
$id=$view->action(['csrf'=>'local-csrf','operation'=>'chat-create','title'=>'Eigene neue Unterhaltung','people'=>[$actors['editor']]],[]);
check($admin->get($id)['owner_id']===$actors['admin'],'UI creates thread with own owner');
denied(fn()=>$view->action(['csrf'=>'wrong','operation'=>'chat-send','id'=>$id,'body'=>'Denied','request_key'=>$key()],[]),'chat adapter checks CSRF');
$request=$key();$first=$admin->send($id,'Erste Nachricht',$request);
check(count($editorAlerts->queue())===1&&$adminAlerts->queue()===[],'only opted in recipient gets local queue event');
check($readerAlerts->queue()===[],'nonmember never gets notification');
$admin->send($id,'Erste Nachricht',$request);check(count($editorAlerts->queue())===1,'retry does not duplicate outbox');
$editor->markRead($id,(int)$first['seq']);check($editorAlerts->queue()===[],'read acknowledges pending notification');
$replyKey=$key();$reply=$editor->send($id,'Antwort mit Referenz',$replyKey,(int)$first['seq']);
$replyRows=$admin->history($id);$last=end($replyRows);check((int)$last['reply_to']===(int)$first['seq']&&$last['reply_body']==='Erste Nachricht','reply points to same thread message');
check($editor->send($id,'Antwort mit Referenz',$replyKey,(int)$first['seq'])['seq']===$reply['seq'],'reply retry idempotent');
denied(fn()=>$editor->send($id,'Antwort mit Referenz',$replyKey),'request cannot change reply semantics');
$other=$admin->create('Andere Unterhaltung',[$actors['editor']]);$foreignMessage=$admin->send($other['id'],'Nicht in erstem Thread',$key());
denied(fn()=>$admin->send($id,'Cross thread reply',$key(),(int)$foreignMessage['seq']),'cross thread reply rejected');
denied(fn()=>$reader->send($id,'Read only reply',$key(),(int)$first['seq']),'nonmember reply rejected');
$admin->edit($id,(int)$first['seq'],'Korrigierter Ursprung',1);$rows=$admin->history($id);check($rows[1]['reply_body']==='Korrigierter Ursprung','reply resolves current parent text without changing reference');

$source=$root.'/synthetic.png';$image=imagecreatetruecolor(60,40);imagefill($image,0,0,imagecolorallocate($image,30,90,60));imagepng($image,$source);unset($image);file_put_contents($source,'SYNTHETIC_TRAILING_BYTES',FILE_APPEND);
$uploadKey=$key();$imageMessage=$files->send($id,'',$uploadKey,$source,'../../source.php',(int)$first['seq']);
$imageFile=$files->file($id,(int)$imageMessage['seq']);
check($imageFile['mime']==='image/png'&&$imageFile['name']==='source.png','image MIME determines safe download extension');
check(!str_contains(file_get_contents($imageFile['path']),'SYNTHETIC_TRAILING_BYTES'),'image upload decodes and reencodes');
check(hash_file('sha256',$imageFile['path'])===$imageFile['sha256'],'file hash verified');
check($editorFiles->file($id,(int)$imageMessage['seq'])['sha256']===$imageFile['sha256'],'thread participant can download');
denied(fn()=>$readerFiles->file($id,(int)$imageMessage['seq']),'nonmember cannot download');
denied(fn()=>$foreignFiles->file($id,(int)$imageMessage['seq']),'foreign club cannot download');
denied(fn()=>$files->file($other['id'],(int)$imageMessage['seq']),'file is bound to thread');
$diskBefore=count(glob($root.'/files/*/*.bin'));
check($files->send($id,'',$uploadKey,$source,'../../source.php',(int)$first['seq'])['seq']===$imageMessage['seq'],'same attachment retry returns same message');
check(count(glob($root.'/files/*/*.bin'))===$diskBefore,'retry cleans temporary duplicate file');
denied(fn()=>$files->send($id,'Changed caption',$uploadKey,$source,'source.php',(int)$first['seq']),'attachment request change rejected');
check(count(glob($root.'/files/*/*.bin'))===$diskBefore,'failed retry leaves no private file orphan');
$countBefore=count($admin->messages($id));$queueBefore=count($editorAlerts->queue());
denied(fn()=>$files->send($id,'Bad reply',$key(),$source,'source.png',(int)$foreignMessage['seq']),'file reply from another thread denied');
check(count($admin->messages($id))===$countBefore&&count($editorAlerts->queue())===$queueBefore,'failed file reply atomically rolls back message and notification');
check(count(glob($root.'/files/*/*.bin'))===$diskBefore,'failed file reply removes prepared file');
denied(fn()=>$view->action(['csrf'=>'local-csrf','operation'=>'chat-send','id'=>$id,'request_key'=>$key(),'body'=>'Fake upload'],['chat_file'=>['error'=>UPLOAD_ERR_OK,'tmp_name'=>$source,'name'=>'fake.png']]),'CLI file cannot impersonate HTTP upload');
$text=$root.'/synthetic.txt';file_put_contents($text,"Eigener UTF-8 Text 🎶\nZweite Zeile");
$textMessage=$files->send($id,'Textdatei',$key(),$text,'Text.txt');$textFile=$files->file($id,(int)$textMessage['seq']);
check($textFile['mime']==='text/plain'&&file_get_contents($textFile['path'])===file_get_contents($text),'UTF8 text attachment retained');
$pdf=$root.'/synthetic.pdf';file_put_contents($pdf,"%PDF-1.4\n1 0 obj\n<< /Type /Catalog >>\nendobj\ntrailer\n<< /Root 1 0 R >>\n%%EOF\n");
$pdfMessage=$files->send($id,'PDF Download',$key(),$pdf,'Eigenes Testdokument.pdf');check($files->file($id,(int)$pdfMessage['seq'])['mime']==='application/pdf','passive PDF download accepted');
$activePdf=$root.'/active.pdf';file_put_contents($activePdf,"%PDF-1.4\n/JavaScript (synthetic)\n%%EOF");
denied(fn()=>$files->send($id,'',$key(),$activePdf,'active.pdf'),'explicit PDF active content rejected');
$html=$root.'/active.html';file_put_contents($html,'<!doctype html><html><script>synthetic()</script></html>');denied(fn()=>$files->send($id,'',$key(),$html,'disguised.txt'),'HTML denied as text attachment');
$binary=$root.'/binary.txt';file_put_contents($binary,"text\0binary");denied(fn()=>$files->send($id,'',$key(),$binary,'binary.txt'),'binary bytes denied as text');
$large=$root.'/large.txt';file_put_contents($large,str_repeat('x',8*1024*1024+1));denied(fn()=>$files->send($id,'',$key(),$large,'large.txt'),'8MiB file limit enforced');
$originalBytes=file_get_contents($imageFile['path']);file_put_contents($imageFile['path'],'tampered');denied(fn()=>$files->file($id,(int)$imageMessage['seq']),'corrupt stored file fails integrity check');file_put_contents($imageFile['path'],$originalBytes);
denied(fn()=>$readerFiles->send($id,'',$key(),$source,'readonly.png'),'reader cannot upload');
$rendered=$view->manager($id);check(str_contains($rendered,'/chat-image/'.$id.'/'.$imageMessage['seq']),'image message exposes authorized preview route');
check(str_contains($rendered,'/chat-file/'.$id.'/'.$pdfMessage['seq'])&&!str_contains($rendered,$root),'attachment HTML has route and no storage path');
check(str_contains($rendered,'data-chat-reply=')&&str_contains($rendered,'Antwort auf Nachricht'),'reply UI and origin preview rendered');

$view->action(['csrf'=>'local-csrf','operation'=>'poll-create','id'=>$id,'question'=>'Welcher Abend?','options'=>"Freitag\nSamstag\n0",'request_key'=>$key()],[]);
$rows=$admin->history($id);$pollMessage=end($rows);$pollId=$pollMessage['poll_id'];$polls=new Polls($db,$adminAccess);$poll=$polls->get($id,$pollId);
check(array_column($poll['options'],'label')===['Freitag','Samstag','0'],'poll adapter preserves zero answer');
$editorView->action(['csrf'=>'local-csrf','operation'=>'poll-vote','id'=>$id,'poll_id'=>$pollId,'option'=>1,'version'=>0,'request_key'=>$key()],[]);
check($polls->get($id,$pollId)['total_votes']===1,'poll UI action records vote');
$editorView->action(['csrf'=>'local-csrf','operation'=>'poll-vote','id'=>$id,'poll_id'=>$pollId,'option'=>2,'version'=>1,'request_key'=>$key()],[]);
$poll=$polls->get($id,$pollId);check((int)$poll['options'][0]['votes']===0&&(int)$poll['options'][1]['votes']===1,'poll UI changes own vote');
check(str_contains($editorView->manager($id),'Stimme ändern')&&str_contains($editorView->manager($id),'<progress'),'poll renders own choice and result bars');
$view->action(['csrf'=>'local-csrf','operation'=>'poll-close','id'=>$id,'poll_id'=>$pollId,'version'=>1],[]);
check(!$polls->get($id,$pollId)['open']&&str_contains($view->manager($id),'Umfrage beendet'),'poll close action and results rendered');
denied(fn()=>$editorView->action(['csrf'=>'local-csrf','operation'=>'poll-vote','id'=>$id,'poll_id'=>$pollId,'option'=>1,'version'=>2,'request_key'=>$key()],[]),'closed poll rejects UI vote');

$view->action(['csrf'=>'local-csrf','operation'=>'chat-add','id'=>$id,'people'=>[$actors['reader']]],[]);
check(count($reader->people($id))===3&&$readerFiles->file($id,(int)$imageMessage['seq'])['mime']==='image/png','added member can read history and attachments');
check(!str_contains($readerView->manager($id),'class="chat-compose"')&&!str_contains($readerView->manager($id),'value="poll-vote"'),'read-only member gets no send/vote controls');
$editorAlerts->mute($id,true);check($editorAlerts->muted($id),'thread mute persisted');
$pending=count($editorAlerts->queue());$admin->send($id,'Während stumm',$key());check(count($editorAlerts->queue())===$pending,'muted thread does not enqueue');
check(count($readerAlerts->queue())===1,'unmuted reader member receives hint');
$reader->markRead($id,PHP_INT_MAX);check($readerAlerts->queue()===[],'read-only member can acknowledge hints');
$editorAlerts->mute($id,false);$admin->send($id,'Nach Stummschaltung',$key());check(count($editorAlerts->queue())===$pending+1,'unmute queues future messages only');
$state=$editorAlerts->state();$editorAlerts->set(false,$state['version']);check($editorAlerts->queue()===[],'global disable cancels pending hints');
$admin->send($id,'Optout',$key());check($editorAlerts->queue()===[],'optout prevents new hints');
$editorAlerts->set(true,$editorAlerts->state()['version']);
$device=$key();$subscription=['endpoint'=>'https://push.example.invalid/synthetic','keys'=>['p256dh'=>str_repeat('A',87),'auth'=>str_repeat('B',22)]];
$editorAlerts->device($device,true,$subscription);$deviceState=$editorAlerts->state();
check(count($deviceState['devices'])===1&&$deviceState['devices'][0]['device_key']===hash('sha256',$device),'device stored by random-key hash');
check(!str_contains(json_encode($deviceState),'push.example.invalid')&&!str_contains(json_encode($deviceState),str_repeat('A',87)),'device state never returns endpoint or subscription keys');
check($deviceState['transport']==='disabled'&&$deviceState['closed_browser_available']===false,'no external delivery claimed');
$editorAlerts->device($device,true);check(count($editorAlerts->state()['devices'])===1,'device registration deduplicated');
denied(fn()=>$editorAlerts->device($key(),true,['endpoint'=>'http://example.invalid','keys'=>$subscription['keys']]),'invalid subscription endpoint rejected without network');
$admin->send($id,'Gerätehinweis',$key());check(count($editorAlerts->queue())===1,'queue can be prepared without a transport');
$editorAlerts->disableDevices();check($editorAlerts->queue()===[]&&(int)$editorAlerts->state()['devices'][0]['enabled']===0,'device revoke disables and cancels pending');
$admin->send($id,'Vor Austritt',$key());check(count($editorAlerts->queue())===1,'optin remains separate from device registration');
$editorView->action(['csrf'=>'local-csrf','operation'=>'chat-leave','id'=>$id],[]);
check($editorAlerts->queue()===[],'leaving cancels thread notifications');
denied(fn()=>$editorFiles->file($id,(int)$imageMessage['seq']),'leaving immediately revokes file ACL');
denied(fn()=>$editorAlerts->mute($id,false),'former member cannot modify thread mute');
denied(fn()=>$editorView->status($id),'former member cannot poll message status');
$status=$view->status($id);check($status['actor_id']===$actors['admin']&&strlen($status['stamp'])===64,'status actor and conversation stamp available');
check(!str_contains(json_encode($status),'Korrigierter Ursprung'),'status notifications contain no message body');
Db::run($db,'DELETE FROM native_grants WHERE actor_id=? AND module="chat" AND capability="read"',[$actors['reader']]);
denied(fn()=>$readerAlerts->queue(),'revoked read capability blocks queued notices');
denied(fn()=>$readerFiles->file($id,(int)$imageMessage['seq']),'revoked read capability blocks attachment');

$history=$admin->create('Eigene Verlaufspaginierung',[$actors['editor']]);
for($i=0;$i<105;$i++)$admin->send($history['id'],'Synthetische Historie '.$i,$key());
$latest=$admin->history($history['id']);$older=$admin->history($history['id'],(int)$latest[0]['seq']);
check(count($latest)===100&&count($older)===5,'latest and older messages are reachable without truncation');
check(end($older)['seq']<$latest[0]['seq'],'history pages do not overlap');
check(str_contains($view->manager($history['id'],(int)$latest[0]['seq']),'data-history="1"'),'history view disables automatic latest replacement');
echo 'Native chat workflows: '.$checks.' checks passed; isolated MySQL, synthetic files, no network transport.'.PHP_EOL;
